  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Le mal surgit sous toutes les formes imaginables, et pas seulement dans des cœurs emplis de destruction et de chaos. Les tyrans sont des antipaladins manipulateurs et respectueux de la loi, de fins strat&#232;ges qui arrangent les choses en coulisse pour s&#39;assurer que, quoi qu&#39;il arrive, le mal gagne toujours et le tyran avec. Contrairement aux autres antipaladins, les tyrans s&#39;associent volontiers &#224; des cr&#233;atures bonnes, afin de les manipuler pour qu&#39;elles accomplissent des actes mal&#233;fiques.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Code du tyran&lt;a class=&quot;headeranchor&quot; id=&quot;Code_du_tyran_0&quot; href=&quot;#Code_du_tyran_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-Lintrigue.html#9&quot; title=&quot;FAQ- de l&amp;#39;Art de l&amp;#39;intrigue&quot;&gt;→&lt;/a&gt; Tyran : Le tyran doit-il vraiment avoir les armes anarchiques comme option pour sa faveur des fi&#233;lons ? Qu&#39;en est-il de &lt;i&gt;cercle magique contre la Loi&lt;/i&gt;, &lt;i&gt;protection contre la Loi (partag&#233;)&lt;/i&gt; et &lt;i&gt;rejet de la Loi&lt;/i&gt; ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Non, le &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;tyran&lt;/a&gt;&lt;/u&gt; devrait avoir les armes &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Axiomatique.html&quot; title=&quot;axiomatique (propri&#233;t&#233;)&quot;&gt;axiomatiques&lt;/a&gt;&lt;/i&gt; dans le cadre de sa &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;, et les sorts devraient tous &#234;tre contre le Chaos, et non pas la Loi. Cela sera refl&#233;t&#233; dans le prochain errata.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Un tyran doit &#234;tre d&#39;alignement Loyal Mauvais et perd toutes ses capacit&#233;s de classe, &#224; l&#39;exception des formations aux armes et armures, s&#39;il commet volontairement et par altruisme des actes bons. Cela ne signifie pas que le tyran ne peut pas faire des actions que quelqu&#39;un d&#39;autre pourrait qualifier de bonnes, mais que ces actions doivent toujours &#234;tre au service de ses propres ambitions. Le code d&#39;un tyran exige qu&#39;il place ses propres desseins sinistres au-dessus de tout, qu&#39;il respecte l&#39;autorit&#233; l&#233;gitime m&#234;me s&#39;il se sert de ses failles &#224; ses propres fins, qu&#39;il impose la tyrannie et qu&#39;il punisse tous ceux qui osent le contester. Un tyran peut accepter des subordonn&#233;s de n&#39;importe quel alignement ; il ne se soucie pas de savoir qui le sert, mais seulement qu&#39;ils lui soient enti&#232;rement loyaux. Il peut m&#234;me travailler aux c&#244;t&#233;s d&#39;individus d&#39;alignement Bon, tant qu&#39;il les manipule en secret.&lt;br /&gt;&lt;br /&gt;Les sorts du &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;registre&lt;/a&gt; du Chaos dans la &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Sorts-Dantipaladin.html&quot; title=&quot;Liste des sorts d&amp;#39;antipaladin&quot;&gt;liste des sorts d&#39;antipaladin&lt;/a&gt; sont remplac&#233;s par leur &#233;quivalent de la Loi pour un tyran. Ainsi, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-Magique-Contre-La-Loi.html&quot; title=&quot;Cercle magique contre la Loi&quot;&gt;cercle magique contre la Loi&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-La-Loi.html&quot; title=&quot;Protection contre la Loi&quot;&gt;protection contre la Loi&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-La-Loi-(Partag&#233;).html&quot; title=&quot;Protection contre la Loi (partag&#233;)&quot;&gt;protection contre la Loi (partag&#233;)&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejet-De-La-Loi.html&quot; title=&quot;Rejet de la Loi&quot;&gt;rejet de la Loi&lt;/a&gt;&lt;/i&gt; sont respectivement remplac&#233;s par &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-Magique-Contre-Le-Chaos.html&quot; title=&quot;Cercle magique contre le Chaos&quot;&gt;cercle magique contre le Chaos&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Chaos.html&quot; title=&quot;Protection contre le Chaos&quot;&gt;protection contre le Chaos&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Chaos-(Partag&#233;).html&quot; title=&quot;Protection contre le Chaos (partag&#233;)&quot;&gt;protection contre le Chaos (partag&#233;)&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejet-Du-Chaos.html&quot; title=&quot;Rejet du Chaos&quot;&gt;rejet du Chaos&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;Cela modifie la liste des sorts de l&#39;antipaladin, le &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CODEDECONDUITE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;code de conduite&lt;/a&gt; de l&#39;antipaladin et les capacit&#233;s associ&#233;es, ainsi que la section sur les &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#ANCIENSANTIPALADINS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;anciens antipaladins&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_1&quot; href=&quot;#Comp&#233;tences_de_classe_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un tyran ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe, mais en retire &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;. Cela modifie les comp&#233;tences de classe de l&#39;antipaladin.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Faveur des diables (Mag)&lt;a class=&quot;headeranchor&quot; id=&quot;Faveur_des_diables_Mag_2&quot; href=&quot;#Faveur_des_diables_Mag_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, si le tyran choisi d&#39;acqu&#233;rir les services d&#39;un serviteur fi&#233;lon avec sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;, il doit choisir un animal &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREFIELONNE&quot; title=&quot;Les arch&#233;types&quot;&gt;fi&#233;lon&lt;/a&gt; ou une cr&#233;ature avec les sous-types &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Loi.html&quot; title=&quot;Loi (sous-type)&quot;&gt;Loi&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mal.html&quot; title=&quot;Mal (sous-type)&quot;&gt;Mal&lt;/a&gt;. S&#39;il choisit de pouvoir enchanter son arme gr&#226;ce &#224; un esprit fi&#233;lon, il peut y ajouter la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Axiomatique.html&quot; title=&quot;axiomatique (propri&#233;t&#233;)&quot;&gt;axiomatique&lt;/a&gt;&lt;/i&gt;, mais pas la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Anarchique.html&quot; title=&quot;anarchique (propri&#233;t&#233;)&quot;&gt;anarchique&lt;/a&gt;&lt;/i&gt;. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;.
